func valueExtractionRun(p unsafe.Pointer, c int32) any {
	r := (*extractioneval.ExtractionRun)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Task)
	case 4:
		return string(r.Status)
	case 5:
		return string(r.ProviderID)
	case 6:
		return r.ProviderName
	case 7:
		if r.ProviderModel == "" {
			return nil
		}
		return r.ProviderModel
	case 8:
		if r.ServedModel == "" {
			return nil
		}
		return r.ServedModel
	case 9:
		return int64(r.CaseLimit)
	case 10:
		return int64(r.CasesTotal)
	case 11:
		return int64(r.CasesCompleted)
	case 12:
		return int64(r.CasesFailed)
	case 13:
		return int64(r.CasesSkipped)
	case 14:
		return int64(r.ScoredCount)
	case 15:
		return int64(r.CorrectCount)
	case 16:
		return int64(r.CorrectedCount)
	case 17:
		return int64(r.MissedCount)
	case 18:
		return int64(r.UnconfirmedCount)
	case 19:
		return int64(r.UnscoredCount)
	case 20:
		return r.Accuracy
	case 21:
		if r.FieldAccuracy == nil {
			return keel.EmptyJSONArray
		}
		return r.FieldAccuracy
	case 22:
		return r.CostUSD
	case 23:
		return r.InputTokens
	case 24:
		return r.OutputTokens
	case 25:
		return r.AvgLatencyMs
	case 26:
		if r.StopReason == "" {
			return nil
		}
		return r.StopReason
	case 27:
		if r.FailureMessage == "" {
			return nil
		}
		return r.FailureMessage
	case 28:
		return string(r.RequestedByID)
	case 29:
		if r.WorkflowID == "" {
			return nil
		}
		return r.WorkflowID
	case 30:
		if r.StartedAt == nil {
			return nil
		}
		return *r.StartedAt
	case 31:
		if r.FinishedAt == nil {
			return nil
		}
		return *r.FinishedAt
	case 32:
		return r.Version
	case 33:
		return r.CreatedAt
	case 34:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateExtractionRun(ctx context.Context, p unsafe.Pointer) error {
	return (*extractioneval.ExtractionRun)(p).BeforeCreate(ctx)
}

